import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

matvec_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void matvec_kernel(const float* __restrict__ A,
                               const float* __restrict__ B,
                               float* __restrict__ C,
                               int M, int K) {
    const int BLOCK_ROWS = 4;
    const int TILE_K4 = 1024; // number of float4 elements per shared-memory tile (per buffer)
    extern __shared__ float4 sB_all[];
    float4* sB[2];
    sB[0] = sB_all;
    sB[1] = sB_all + TILE_K4;
    int row_start = blockIdx.x * BLOCK_ROWS;
    int tid = threadIdx.x;
    int nthreads = blockDim.x;
    int K4 = K / 4;
    const float4* B_vec = reinterpret_cast<const float4*>(B);
    const float4* A_row[BLOCK_ROWS];
#pragma unroll
    for (int r = 0; r < BLOCK_ROWS; ++r) {
        int row = row_start + r;
        A_row[r] = (row < M) ? reinterpret_cast<const float4*>(A + (size_t)row * K) : nullptr;
    }
    float sum[BLOCK_ROWS];
#pragma unroll
    for (int r = 0; r < BLOCK_ROWS; ++r) sum[r] = 0.0f;
    int num_tiles = (K4 + TILE_K4 - 1) / TILE_K4;
    int cur = 0;
    // preload first tile
    if (num_tiles > 0) {
        int tile_len0 = min(TILE_K4, K4 - 0);
        for (int i = tid; i < tile_len0; i += nthreads) {
            sB[cur][i] = B_vec[i];
        }
    }
    __syncthreads();
    for (int t = 0; t < num_tiles; ++t) {
        int tile_start = t * TILE_K4;
        int tile_len = min(TILE_K4, K4 - tile_start);
        int next = cur ^ 1;
        int next_tile_start = tile_start + TILE_K4;
        int next_tile_len = (t + 1 < num_tiles) ? min(TILE_K4, K4 - next_tile_start) : 0;
        // prefetch next tile into the other buffer; this overlaps with the
        // compute loop below since it targets a different shared-memory buffer.
        if (next_tile_len > 0) {
            for (int i = tid; i < next_tile_len; i += nthreads) {
                sB[next][i] = B_vec[next_tile_start + i];
            }
        }
        for (int i = tid; i < tile_len; i += nthreads) {
            float4 b = sB[cur][i];
#pragma unroll
            for (int r = 0; r < BLOCK_ROWS; ++r) {
                if (A_row[r] != nullptr) {
                    float4 a = A_row[r][tile_start + i];
                    sum[r] += a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
                }
            }
        }
        __syncthreads();
        cur = next;
    }
    // warp-level reduction per row
    __shared__ float warpSums[BLOCK_ROWS][32];
    int lane = tid % 32;
    int wid = tid / 32;
    int num_warps = (nthreads + 31) / 32;
#pragma unroll
    for (int r = 0; r < BLOCK_ROWS; ++r) {
        float val = sum[r];
        for (int offset = 16; offset > 0; offset >>= 1) {
            val += __shfl_down_sync(0xffffffff, val, offset);
        }
        if (lane == 0) {
            warpSums[r][wid] = val;
        }
    }
    __syncthreads();
    if (wid == 0) {
#pragma unroll
        for (int r = 0; r < BLOCK_ROWS; ++r) {
            float val = (lane < num_warps) ? warpSums[r][lane] : 0.0f;
            for (int offset = 16; offset > 0; offset >>= 1) {
                val += __shfl_down_sync(0xffffffff, val, offset);
            }
            if (lane == 0) {
                int row = row_start + r;
                if (row < M) {
                    C[row] = val;
                }
            }
        }
    }
}
torch::Tensor matvec_cuda(torch::Tensor A, torch::Tensor B) {
    A = A.contiguous();
    B = B.contiguous();
    int M = A.size(0);
    int K = A.size(1);
    auto C = torch::empty({M, 1}, A.options());
    const int threads = 256;
    const int BLOCK_ROWS = 4;
    const int blocks = (M + BLOCK_ROWS - 1) / BLOCK_ROWS;
    const int TILE_K4 = 1024;
    size_t shared_mem_size = 2 * TILE_K4 * sizeof(float4);
    matvec_kernel<<<blocks, threads, shared_mem_size>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, K
    );
    return C;
}
"""

matvec_cpp_source = "torch::Tensor matvec_cuda(torch::Tensor A, torch::Tensor B);"

matvec_module = load_inline(
    name="matvec_module",
    cpp_sources=matvec_cpp_source,
    cuda_sources=matvec_source,
    functions=["matvec_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs matrix-vector multiplication (C = A * B)
    using a custom CUDA kernel with float4 vectorized loads and warp-shuffle
    reduction.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matvec = matvec_module

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        A = A.cuda()
        B = B.cuda()
        return self.matvec.matvec_cuda(A, B)


M = 256 * 8  # 2048
K = 131072 * 8  # 1048576


def get_inputs():
    A = torch.rand(M, K)
    B = torch.rand(K, 1)
    return [A, B]


def get_init_inputs():
    return []

